/* Запрос на количество карт, которые были созданы Джоном Авен и у которых нет мощной версии */
SELECT COUNT(*) 
FROM cards AS c
WHERE c.artist = 'John Avon'
AND NOT EXISTS (
    SELECT 1
    FROM cards AS cf
    WHERE cf.artist = 'John Avon'
    AND cf.mtgofoilid IS NOT NULL
);

SELECT COUNT(*) 
FROM cards 
WHERE originaltype = 'Summon - Angel' AND subtypes NOT LIKE '%Angel%';

/* Считаем количество карт с черной границей и выводим их ID */
SELECT COUNT(id) AS count_black_border_cards, id 
FROM cards 
WHERE bordercolor = 'black' 
GROUP BY id;

SELECT DISTINCT keywords 
FROM cards 
WHERE name = 'Angel of Mercy';

SELECT DISTINCT convertedmanacost 
FROM cards 
WHERE name = 'Ancestor''s Chosen';

/* Запрос на подсчет количества карт, которые были созданы Аароном Миллером и считаются очень мощными */

SELECT COUNT(*) AS count_of_powerful_cards
FROM cards c
JOIN foreign_data fd ON c.id = fd.id
WHERE c.artist LIKE '%Aaron Miller%' AND fd.flavortext LIKE '%very powerful%';

SELECT EXISTS (
    SELECT 1 
    FROM cards c
    JOIN set_translations st ON c.setcode = st.setcode
    WHERE c.name LIKE '%Angel of Mercy%' AND st.translation LIKE '%Magic: The Gathering Online%'
);
